metadata.er-schema:
{
  "title": "looply · 营销活动（促销折扣）实体关系图",
  "version": "v1.0 · 2026-07-13",
  "tables": [
    {
      "name": "promotion",
      "comment": "促销活动",
      "columns": [
        {
          "name": "id",
          "comment": "活动ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_name",
          "comment": "活动名称",
          "constraint": ""
        },
        {
          "name": "discount_type",
          "comment": "折扣类型 product商品/order订单",
          "constraint": ""
        },
        {
          "name": "trigger_type",
          "comment": "触发方式 auto自动/code优惠码",
          "constraint": ""
        },
        {
          "name": "value_type",
          "comment": "折扣值类型 percentage百分比/fixed固定金额",
          "constraint": ""
        },
        {
          "name": "percentage_value",
          "comment": "百分比值（value_type=percentage用）",
          "constraint": ""
        },
        {
          "name": "product_scope",
          "comment": "商品范围 all全部/category品类/brand品牌/listing指定（仅商品折扣）",
          "constraint": ""
        },
        {
          "name": "min_type",
          "comment": "门槛类型 none无/amount满额/quantity满件",
          "constraint": ""
        },
        {
          "name": "min_quantity",
          "comment": "满件门槛值（min_type=quantity用）",
          "constraint": ""
        },
        {
          "name": "max_item_count",
          "comment": "每单最多作用件数（商品折扣可选封顶）",
          "constraint": ""
        },
        {
          "name": "total_usage_limit",
          "comment": "总使用次数上限（空=不限）",
          "constraint": ""
        },
        {
          "name": "per_user_limit",
          "comment": "每人使用次数上限（空=不限）",
          "constraint": ""
        },
        {
          "name": "combines_with",
          "comment": "可叠加折扣类【V2预留】",
          "constraint": ""
        },
        {
          "name": "eligibility",
          "comment": "适用人群 all全部【人群定向V2预留】",
          "constraint": ""
        },
        {
          "name": "budget_total",
          "comment": "活动预算总额【V2预留】",
          "constraint": ""
        },
        {
          "name": "budget_spent",
          "comment": "已消耗预算【V2预留】",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 draft/scheduled/active/paused/ended",
          "constraint": ""
        },
        {
          "name": "start_at",
          "comment": "开始时间",
          "constraint": ""
        },
        {
          "name": "end_at",
          "comment": "结束时间（空=长期）",
          "constraint": ""
        },
        {
          "name": "created_by",
          "comment": "创建人",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "聚合根。金额预算池/人群定向为 V2 预留字段"
    },
    {
      "name": "promotion_market",
      "comment": "活动-市场明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_id",
          "comment": "活动ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "投放市场ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "currency_code",
          "comment": "币种（录值口径）",
          "constraint": ""
        },
        {
          "name": "fixed_amount",
          "comment": "固定金额折扣值（value_type=fixed用）",
          "constraint": ""
        },
        {
          "name": "min_amount",
          "comment": "满额门槛值（min_type=amount用，按币种）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "双职责：①投放市场范围 ②固定金额/满额门槛按币种录值，无实时汇率"
    },
    {
      "name": "promotion_target",
      "comment": "活动商品范围明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_id",
          "comment": "活动ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "target_type",
          "comment": "圈选类型 category品类/brand品牌/listing指定商品",
          "constraint": ""
        },
        {
          "name": "target_id",
          "comment": "目标ID（对应category_id/brand_id/listing_id）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "仅商品折扣使用；product_scope=all 时无记录"
    },
    {
      "name": "promotion_code",
      "comment": "优惠码",
      "columns": [
        {
          "name": "id",
          "comment": "优惠码ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_id",
          "comment": "活动ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "code",
          "comment": "优惠码",
          "constraint": "UNIQUE"
        },
        {
          "name": "status",
          "comment": "状态 active/disabled",
          "constraint": ""
        },
        {
          "name": "used_count",
          "comment": "已使用次数（冗余计数）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "仅 trigger_type=code 使用；一活动可多码做定向发放"
    },
    {
      "name": "promotion_redemption",
      "comment": "核销流水",
      "columns": [
        {
          "name": "id",
          "comment": "核销ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "promotion_id",
          "comment": "活动ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "code_id",
          "comment": "优惠码ID（自动折扣为空）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "discount_amount",
          "comment": "本单实际让利额（汇总）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "redeemed_at",
          "comment": "核销时间",
          "constraint": ""
        }
      ],
      "note": "一活动一订单一条。总次数看计数、每人次数看(promotion,user)、预算累加落此"
    },
    {
      "name": "order_discount_line",
      "comment": "行级让利明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_item_id",
          "comment": "订单商品行ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "promotion_id",
          "comment": "活动ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "redemption_id",
          "comment": "核销ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "discount_type",
          "comment": "折扣类型 product/order（冗余便于报表）",
          "constraint": ""
        },
        {
          "name": "original_amount",
          "comment": "行原价金额",
          "constraint": ""
        },
        {
          "name": "discount_amount",
          "comment": "行让利额（订单折扣为摊分后）",
          "constraint": ""
        },
        {
          "name": "net_amount",
          "comment": "行净价 = 原价 - 让利",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "核心：原价/让利/净价三留痕。订单折扣按行金额占比反摊到此，供退款与三方结算取净价"
    },
    {
      "name": "ref_product",
      "comment": "商品域（引用）",
      "columns": [
        {
          "name": "listing_id",
          "comment": "在售商品ID",
          "constraint": ""
        },
        {
          "name": "spu_id",
          "comment": "SPU ID",
          "constraint": ""
        },
        {
          "name": "category_id",
          "comment": "品类ID",
          "constraint": ""
        },
        {
          "name": "brand_id",
          "comment": "品牌ID",
          "constraint": ""
        }
      ],
      "note": "圈选活动商品时只读；商品折扣命中维度"
    },
    {
      "name": "ref_market",
      "comment": "market（引用）",
      "columns": [
        {
          "name": "market_id",
          "comment": "市场ID",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        }
      ],
      "note": "活动归属市场、币种口径来源"
    },
    {
      "name": "ref_user",
      "comment": "用户（引用）",
      "columns": [
        {
          "name": "user_id",
          "comment": "用户ID",
          "constraint": ""
        }
      ],
      "note": "核销归属用户，每人限次判定"
    },
    {
      "name": "ref_order",
      "comment": "订单（引用）",
      "columns": [
        {
          "name": "order_id",
          "comment": "订单ID",
          "constraint": ""
        },
        {
          "name": "order_item_id",
          "comment": "订单商品行ID",
          "constraint": ""
        }
      ],
      "note": "让利落库对象，退款/结算读取净价"
    }
  ],
  "relations": [
    {
      "from": "promotion_market",
      "to": "promotion",
      "type": "N:1",
      "label": "投放市场",
      "penwidth": 1.4
    },
    {
      "from": "promotion_target",
      "to": "promotion",
      "type": "N:1",
      "label": "圈选商品"
    },
    {
      "from": "promotion_code",
      "to": "promotion",
      "type": "N:1",
      "label": "优惠码"
    },
    {
      "from": "promotion_redemption",
      "to": "promotion",
      "type": "N:1",
      "label": "核销",
      "penwidth": 1.4
    },
    {
      "from": "promotion_redemption",
      "to": "promotion_code",
      "type": "N:1",
      "label": "码核销"
    },
    {
      "from": "order_discount_line",
      "to": "promotion_redemption",
      "type": "N:1",
      "label": "摊分明细",
      "penwidth": 1.4
    },
    {
      "from": "order_discount_line",
      "to": "promotion",
      "type": "N:1",
      "label": "归属活动"
    },
    {
      "from": "promotion_market",
      "to": "ref_market",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_target",
      "to": "ref_product",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "ref_user",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "promotion_redemption",
      "to": "ref_order",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    },
    {
      "from": "order_discount_line",
      "to": "ref_order",
      "type": "N:1",
      "label": "引用",
      "color": "#9AA0A6",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "让利独立落库": "营销不改商品原价与订单原始金额；让利以 order_discount_line 独立留痕（原价/让利/净价三值）",
    "订单折扣摊分": "订单级让利按各订单行金额占比反摊到 order_discount_line，供退款与三方卖家结算取行级净价",
    "多币种录值": "固定金额折扣值与满额门槛按 promotion_market 逐市场币种录入，无实时汇率换算",
    "用量控制": "总次数看 redemption 计数、每人次数看 (promotion_id,user_id) 计数、有效期看 start_at/end_at",
    "互斥取优_V1": "同一订单多活动命中时取对用户最优的一个；combines_with 预留 Shopify 组合类模型，V2 放开叠加",
    "V2预留": "budget_total/budget_spent(金额预算池)、阶梯门槛、eligibility(人群定向) 为预留字段/虚线关系，本版不落逻辑",
    "范围_V1": "仅平台运营创建；折扣成本默认平台承担；三方商家自主营销为后续版本"
  }
}
